'use strict';

var tape = require('tape');
var ndarray = require('@stdlib/ndarray/base/ctor');
var Float64Array = require('@stdlib/array/float64');
var meankbn = require('@stdlib/stats/base/ndarray/meankbn');

function naiveMean(vals) {
  var s = 0;
  for (var i = 0; i < vals.length; i++) s += vals[i];
  return s / vals.length;
}

tape('compensation helps on an ill-conditioned sequence', function(t) {
  var buf = new Float64Array([1e16, 1, -1e16]);

  // dtype, buffer, shape, strides, offset, order:
  var x = new ndarray('float64', buf, [buf.length], [1], 0, 'row-major');

  var m_naive = naiveMean(buf);
  var m_kbn   = meankbn([ x ]);   // <— ndarray wrappers expect [x], not x

  var target = 1/3;

  var err_naive = Math.abs(m_naive - target);
  var err_kbn   = Math.abs(m_kbn - target);

  t.ok(err_kbn <= err_naive, 'compensated mean is not worse than naive');
  t.ok(err_kbn < 1e-12, 'compensated mean is close to the true mean');
  t.end();
});
